"use strict";

/* A `var` inside an implicit-any JS function that is MONOMORPHIZED more
 * than once. Every row below is called at two (or three) different
 * argument types, so one body is lowered once per instance -- which is
 * the shape that used to hand the IR validator an `assign` with no
 * `varDecl` (SC9001 "assign to undeclared local/global").
 *
 * The CONTROL rows (c*) are the same shapes with `let`/`const`, or a
 * single instantiation: they answer identically on both sides. */

/* R1: the minimised ICE, exactly. */
function r1(p) { var x = typeof p; if (x !== "object") return x; return "obj"; }

/* R2: the `var` is read ZERO times. */
function r2(p) { var x = typeof p; return "z" + String(p).length; }

/* R3: read exactly ONCE. */
function r3(p) { var x = typeof p; return x; }

/* R4: THREE instances of one body, not two. */
function r4(p) { var x = typeof p; return x + "/" + x; }

/* R5: two declarators in ONE `var` statement -- two slots per instance. */
function r5(p) { var a = typeof p, b = "B"; return a + b + a; }

/* R6: REDECLARATION inside one function. JS merges same-name `var`s into
 * ONE binding, so the inner statement must ASSIGN the slot the outer one
 * minted, not open a second. */
function r6(p) { var x = typeof p; if (x !== "") { var x = x + "!"; } return x; }

/* R7: a `var` merging with a PARAMETER of the same name -- `var p = ...`
 * overwrites the argument, which is the bindingIn parameter-merge branch
 * (it writes the memo too, so it needs a monomorphized row of its own).
 * The value assigned must stay inside the parameter's BOUND type: a
 * `var p = typeof p` over a number-bound parameter is a separate,
 * pre-existing SC1090 runtime fence ("'string' values where 'number' is
 * expected"), measured on both sides and not this case's subject. */
function r7(p) { var p = p; return typeof p; }

/* R8: a `var` written in a LOOP. One function-scoped slot that persists
 * across iterations and after the loop: the declaration statement must
 * re-ASSIGN, never re-declare. `i` outliving the loop is the proof. */
function r8(p) {
  var out = "";
  for (var i = 0; i < 3; i++) { var t = typeof p; out = out + t.charAt(0); }
  return out + ":" + i + ":" + t;
}

/* R9: `for (var v of ...)` -- forOfVarTarget's one function-scoped loop
 * binding, which still holds the last element after the loop. */
function r9(p) {
  var seen = "";
  for (var v of [1, 2]) { seen = seen + v; }
  return typeof p + seen + v;
}

/* --- CONTROLS: identical on both sides. If any of these differ, the rows
 * above measure nothing. */
function c1(p) { let x = typeof p; if (x !== "object") return x; return "obj"; }
function c2(p) { const x = typeof p; return x + "/" + x; }
function c3(p) { var x = typeof p; return x + "!"; }

exports.r1a = function () { return r1(1); };
exports.r1b = function () { return r1({}); };
exports.r2a = function () { return r2(1); };
exports.r2b = function () { return r2({}); };
exports.r3a = function () { return r3(1); };
exports.r3b = function () { return r3({}); };
exports.r4a = function () { return r4(1); };
exports.r4b = function () { return r4("s"); };
exports.r4c = function () { return r4({}); };
exports.r5a = function () { return r5(1); };
exports.r5b = function () { return r5({}); };
exports.r6a = function () { return r6(1); };
exports.r6b = function () { return r6({}); };
exports.r7a = function () { return r7(1); };
exports.r7b = function () { return r7({}); };
exports.r8a = function () { return r8(1); };
exports.r8b = function () { return r8({}); };
exports.r9a = function () { return r9(1); };
exports.r9b = function () { return r9({}); };
exports.c1a = function () { return c1(1); };
exports.c1b = function () { return c1({}); };
exports.c2a = function () { return c2(1); };
exports.c2b = function () { return c2({}); };
/* c3 is called at ONE type only: a single instantiation never trips the
 * shared memo, so this row passes on base too. */
exports.c3a = function () { return c3(1); };
